const incoming=$input.first().json; const b=incoming.body||incoming;
const category=String(b.category||'').trim(),location=String(b.location||'').trim(); if(!category||!location) throw new Error('category and location are required');
const count=(v,fallback,upper)=>{const n=Number(v);return Number.isFinite(n)&&n>0?Math.min(Math.floor(n),upper):fallback};
const min_rating=Number.isFinite(Number(b.min_rating))?Math.max(1,Math.min(5,Number(b.min_rating))):1;
const min_review_count=count(b.min_review_count,5,100); const max_results=count(b.max_results,15,50);
const delivery_method=String(b.delivery_method||'in_app').toLowerCase(); const email=String(b.email||'').trim()||null;
if(delivery_method==='email'&&!email) throw new Error('email is required for email delivery');
const whatsapp=String(b.whatsapp||'').trim()||null; const input_json=JSON.stringify({category,location,min_rating,min_review_count,max_results});
return [{json:{search_term:`${category} in ${location}`,category,location,min_rating,min_review_count,max_results,delivery_method,email,whatsapp,input_json}}];

const raw=$input.all().map(i=>i.json);const items=raw.flatMap(r=>Array.isArray(r)?r:Array.isArray(r.items)?r.items:[r]);const params=$('Prepare Review Search Params').first().json;const groups=new Map();
for(const r of items){const place=r.placeId||r.place_id||r.fid||r.placeUrl||r.url||r.title; if(!place)continue; if(!groups.has(place))groups.set(place,{place_id:place,business_name:r.title||r.name||'Unknown business',source_url:r.placeUrl||r.googleMapsUrl||r.url||'',overall_rating:Number(r.totalScore??r.overallRating)||null,review_count_total:Number(r.reviewsCount??r.totalReviews)||0,negative_reviews:[],unanswered_negative_reviews:[]});
const b=groups.get(place);b.review_count_total=Math.max(b.review_count_total,Number(r.reviewsCount??r.totalReviews)||0); const review= r.review||r;const rating=Number(review.stars??review.reviewRating??review.rating);const reply=Boolean(review.responseFromOwnerText||review.ownerAnswer||review.reply);const text=review.text||review.reviewText||'';const date=review.publishedAtDate||review.date||null;
if(Number.isFinite(rating)&&rating<=2){const entry={rating,text,date,hasOwnerReply:reply};b.negative_reviews.push(entry);if(!reply)b.unanswered_negative_reviews.push(entry);}}
return [{json:{businesses:[...groups.values()],params}}];
